"Un despacho de carga. Datos inventados para la práctica."
type Despacho {
  id: ID!
  estado: Estado!
  origen: String!
  destino: String!
  pesoKg: Float!
  observaciones: String!
  cliente: Cliente!
  eventos: [Evento!]!
  ultimoEvento: Evento
}

type Cliente {
  id: ID!
  nombre: String!
  ciudad: String!
  despachos(primeros: Int = 10): [Despacho!]!
}

type Evento {
  id: ID!
  tipo: String!
  lugar: String!
  hora: String!
}

enum Estado { PENDIENTE EN_RUTA ENTREGADO }

type Query {
  despacho(id: ID!): Despacho
  despachos(estado: Estado, primeros: Int = 20): [Despacho!]!
}

type Mutation {
  cerrarDespacho(id: ID!, lugar: String!): Despacho!
}

