// Mini ejecutor: un resolver por campo y un DataLoader de juguete. La «base» es un array que cuenta sus consultas. Datos inventados.
const clientes = Array.from({ length: 20 }, (_, i) => ({ id: i + 1, nombre: `Cliente ${String(i + 1).padStart(4, '0')} S.A.` }));
const despachos = Array.from({ length: 50 }, (_, i) => ({ id: 'D-' + String(i + 1).padStart(6, '0'), clienteId: ((i * 7) % 20) + 1 }));

function crearBase() {
  const b = { consultas: 0, lotes: [] };
  b.despachos = async (n) => { b.consultas++; return despachos.slice(0, n); };
  b.clientePorId = async (id) => { b.consultas++; return clientes.find((c) => c.id === id); };
  b.clientesPorIds = async (ids) => { b.consultas++; b.lotes.push(ids.length); return ids.map((id) => clientes.find((c) => c.id === id)); };
  // un lote MAL escrito: devuelve en el orden de la tabla, no en el orden de las claves pedidas
  b.clientesPorIdsMal = async (ids) => { b.consultas++; b.lotes.push(ids.length); return clientes.filter((c) => ids.includes(c.id)); };
  return b;
}

// DataLoader de juguete: junta las load() del mismo turno del bucle de eventos y llama UNA vez a la función de lote.
function cargador(lote) {
  let cola = [];
  const cache = new Map();
  return {
    load(clave) {
      if (cache.has(clave)) return cache.get(clave); // la misma clave, en el mismo pedido, no se vuelve a pedir
      const p = new Promise((ok) => {
        cola.push({ clave, ok });
        if (cola.length === 1) queueMicrotask(async () => {
          const tanda = cola; cola = [];
          const valores = await lote(tanda.map((x) => x.clave)); // debe volver en el mismo orden que las claves
          tanda.forEach((x, i) => x.ok(valores[i]));
        });
      });
      cache.set(clave, p);
      return p;
    },
  };
}

async function pantalla(modo) {
  const base = crearBase();
  const cl = cargador((ids) => (modo === 'lote-mal' ? base.clientesPorIdsMal(ids) : base.clientesPorIds(ids)));
  const lista = await base.despachos(50);                       // Query.despachos
  const filas = await Promise.all(lista.map(async (d) => {      // Despacho.cliente: un resolver por despacho
    const c = modo === 'ingenuo' ? await base.clientePorId(d.clienteId) : await cl.load(d.clienteId);
    return { id: d.id, esperado: d.clienteId, recibido: c.id };
  }));
  const mal = filas.filter((f) => f.esperado !== f.recibido).length;
  console.log(modo.padEnd(9), '| consultas:', String(base.consultas).padStart(3), '| tamaño de los lotes:', JSON.stringify(base.lotes), '| despachos con el cliente equivocado:', mal);
}
for (const m of ['ingenuo', 'lote', 'lote-mal']) await pantalla(m);

// Recorte de servidor.cjs: un analizador de juguete que mira la consulta ANTES de ejecutarla.
function analizar(doc) {
  const op = doc.definitions.find((d) => d.kind === "OperationDefinition");
  let prof = 0;
  const visitar = (tipo, sel, nivel) => {
    let costo = 0;
    for (const s of sel.selections) {
      if (s.kind !== "Field" || s.name.value.startsWith("__")) continue;
      const def = tipo.getFields()[s.name.value];
      const base = G.getNamedType(def.type);
      prof = Math.max(prof, nivel + 1);
      let mult = 1;                                   // si el campo es una lista, multiplica por «primeros»
      if (G.isListType(G.getNullableType(def.type))) {
        const arg = (s.arguments ?? []).find((a) => a.name.value === "primeros");
        mult = arg ? Math.min(100, Number(arg.value.value)) : 10;
      }
      const hijos = s.selectionSet && G.isObjectType(base) ? visitar(base, s.selectionSet, nivel + 1) : 0;
      costo += mult * (1 + hijos);
    }
    return costo;
  };
  return { profundidad: prof, objetos: visitar(schema.getQueryType(), op.selectionSet, 0) };
}
